const results = $input.item.json.result;
const question = $('Webhook').item.json.body.question;

const documents = results.map(r => ({
  text: r.payload.content || r.payload.pageContent || '',
  id: r.id,
  score: r.score
}));

return [{
  json: {
    question,
    documents
  }
}];

const rerankResults = $input.item.json.results;
const prepData = $('Prepare Rerank Input').item.json;
const question = prepData.question;
const originalDocs = prepData.documents;

const threshold = 0.6;
const filtered = rerankResults
  .filter(r => r.relevance_score >= threshold)
  .slice(0, 4);

let contextString = '';
if (filtered.length === 0) {
  contextString = 'Tidak ada dokumen yang relevan ditemukan.';
} else {
  contextString = filtered
    .map((r, i) => `[Dokumen ${i+1}]\n${originalDocs[r.index].text}`)
    .join('\n\n');
}

return [{
  json: {
    question,
    context: contextString,
    found: filtered.length > 0,
    user_id: $('Webhook').item.json.body.user_id
  }
}];
